import fs from'node:fs';import{loadAnny,loadGNM,loadMHR}from'../teachers.mjs';
const a=loadAnny(),g=loadGNM(),m=loadMHR(),dir=new URL('../research/geometry/',import.meta.url);fs.mkdirSync(dir,{recursive:true});const write=(n,v)=>fs.writeFileSync(new URL(n,dir),new Uint8Array(v.buffer,v.byteOffset,v.byteLength));
const an=a.forward({phenotypes:{age:2/3}}),gn=new Float32Array(g.numVertices*3);g.computeVertices(gn);const mh=m.evaluate();
for(const[n,v,f]of[['anny',an.vertices,a.arrays.faces],['gnm',gn,g.triangles],['mhr',mh.vertices,mh.faces]]){if(!f)throw Error('Missing '+n+' faces');write(n+'-vertices.f32',v);write(n+'-faces.u32',new Uint32Array(f));}
write('gnm-regions.u32',new Uint32Array(g.regionId));write('gnm-components.u32',new Uint32Array(g.componentId));write('gnm-materials.u32',new Uint32Array(g.materialId));write('anny-bone-heads.f32',new Float32Array(an.boneHeads));write('anny-bone-poses.f64',an.bonePoses);write('mhr-joints.f32',mh.joints);write('gnm-joints.f32',g.jointsWorld);fs.writeFileSync(new URL('metadata.json',dir),JSON.stringify({gnm:{regions:g.meta.regionNames,components:g.meta.componentNames,materials:g.meta.materialNames,joints:g.meta.jointNames},anny:{bones:a.boneLabels,pose:'default native rest, age2/3'},mhr:{joints:m.meta.joint_names,units:'centimetres Y-up'}},null,2));
